for _ in range(int(input())):
	(n, k) = map(int, input().split())
	s = input()
	o = s.count('1')
	z = n - o
	k = n // k
	if o % k or z % k:
		print('IMPOSSIBLE')
	else:
		word = '1' * (o // k) + '0' * (z // k)
		rev = word[::-1]
		ans = []
		for i in range(k):
			if i & 1:
				ans.append(word)
			else:
				ans.append(rev)
		print(''.join(ans))
